// ==========================================
// 宏 1：导出法术列表到本地
// ==========================================
const PACK_ID = "naxx-dnd5e-collection-2024.naxx-homerule-item"; // 这里填入你要提取的合集包ID

(async () => {
    const pack = game.packs.get(PACK_ID);
    if (!pack) {
        return ui.notifications.error(`找不到合集包 [${PACK_ID}]，请确认 ID 是否正确。`);
    }

    ui.notifications.info(`正在读取 [${PACK_ID}]，请稍候...`);

    // 获取所有法术并按环数排序
    const index = await pack.getIndex({ fields: ["system.level", "type"] });
    const spells = index.filter(i => i.type === "spell").sort((a, b) => (a.system?.level || 0) - (b.system?.level || 0));

    if (spells.length === 0) {
        return ui.notifications.warn(`该合集包内没有找到法术。`);
    }

    // 整理我们要导出的数据格式
    const outputData = spells.map(s => ({
        "等级": s.system?.level || 0,
        "名称": s.name,
        "UUID": s.uuid // UUID 是 FVTT 跨合集包调用物品的关键
    }));

    // 将数据转换为美观的 JSON 字符串
    const fileContent = JSON.stringify(outputData, null, 2);
    const fileName = `${PACK_ID}_spells_export.json`;

    // 触发 FVTT 内置的本地下载功能
    saveDataToFile(fileContent, "application/json", fileName);
    ui.notifications.info(`成功导出！共包含 ${spells.length} 个法术，正在下载...`);
})();
